R=Path(__file__).resolve().parent
entries=[]
def add(id,title,paths,notes=''):
 refs=[]
 for p in paths:
  p=R/p
  if not p.exists():raise FileNotFoundError(p)
  if p.is_dir():refs.append({'path':str(p.relative_to(R)).replace('\\','/'),'directory':True});continue
  refs.append({'path':str(p.relative_to(R)).replace('\\','/'),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
 entries.append({'id':id,'title':title,'notes':notes,'sources':refs})
